import React, { useEffect, useState } from "react";
import API from "../api"; // Make sure this path is correct
import "./StudentDashboard.css";


export default function StudentDashboard({ user, logout }) {
  const [attendanceRecords, setAttendanceRecords] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [selectedAssignmentId, setSelectedAssignmentId] = useState("");
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    async function fetchData() {
      try {
        const attendanceRes = await API.get("/attendance/my-attendance");
        setAttendanceRecords(attendanceRes.data);

        const assignmentsRes = await API.get("/assignments");
        setAssignments(assignmentsRes.data);

        const submissionsRes = await API.get("/submissions/mine"); // Make sure backend route matches
        setSubmissions(submissionsRes.data);
      } catch (err) {
        alert("Failed to load data");
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedAssignmentId) return alert("Please select an assignment");
    if (!file) return alert("Please select a file to upload");

    const formData = new FormData();
    formData.append("assignmentId", selectedAssignmentId);
    formData.append("file", file);

    // Debug logs to verify values before submit
    console.log("Submitting assignmentId:", selectedAssignmentId);
    console.log("Submitting file:", file);

    try {
      setUploading(true);
      await API.post("/submissions", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      alert("Assignment submitted successfully");

      // Refresh submissions list after successful upload
      const submissionsRes = await API.get("/submissions/mine");
      setSubmissions(submissionsRes.data);

      setSelectedAssignmentId("");
      setFile(null);
      e.target.reset();
    } catch (err) {
      alert("Submission failed");
      console.error("Submission error:", err.response || err);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div style={{ padding: 20, maxWidth: 700, margin: "auto" }}>
      <h1>Student Dashboard</h1>
      <p>
        Welcome, {user.username} (Role: {user.role})
      </p>
      <button onClick={logout} style={{ marginBottom: 20 }}>
        Logout
      </button>

      <h3>Your Attendance</h3>
      {loading ? (
        <p>Loading attendance...</p>
      ) : (
        <table
          border="1"
          cellPadding="8"
          style={{ width: "100%", borderCollapse: "collapse", marginBottom: 30 }}
        >
          <thead>
            <tr>
              <th>Date</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {attendanceRecords.length === 0 ? (
              <tr>
                <td colSpan="2" style={{ textAlign: "center" }}>
                  No attendance records found.
                </td>
              </tr>
            ) : (
              attendanceRecords.map((record, i) => (
                <tr key={i}>
                  <td>{new Date(record.date).toLocaleDateString()}</td>
                  <td style={{ color: record.present ? "green" : "red" }}>
                    {record.present ? "Present" : "Absent"}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      )}

      <h3>Assignments</h3>
      {loading ? (
        <p>Loading assignments...</p>
      ) : assignments.length === 0 ? (
        <p>No assignments available</p>
      ) : (
        <table
          border="1"
          cellPadding="8"
          style={{ width: "100%", borderCollapse: "collapse", marginBottom: 30 }}
        >
          <thead>
            <tr>
              <th>Title</th>
              <th>Description</th>
              <th>Due Date</th>
            </tr>
          </thead>
          <tbody>
            {assignments.map((a) => (
              <tr key={a._id}>
                <td>{a.title}</td>
                <td>{a.content || "—"}</td>
                <td>{new Date(a.dueDate).toLocaleDateString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <h4>Submit Assignment</h4>
      <form onSubmit={handleSubmit} style={{ marginBottom: 30 }}>
        <label>
          Select Assignment:
          <select
            required
            value={selectedAssignmentId}
            onChange={(e) => setSelectedAssignmentId(e.target.value)}
            style={{ marginLeft: 10, marginBottom: 10 }}
          >
            <option value="">-- Select --</option>
            {assignments.map((a) => (
              <option key={a._id} value={a._id}>
                {a.title}
              </option>
            ))}
          </select>
        </label>
        <br />
        <input
          type="file"
          accept=".pdf,.doc,.docx"
          onChange={handleFileChange}
          required
          style={{ marginBottom: 10 }}
        />
        <br />
        <button type="submit" disabled={uploading}>
          {uploading ? "Uploading..." : "Submit Assignment"}
        </button>
      </form>

      <h3>Your Submitted Assignments</h3>
      {loading ? (
        <p>Loading submissions...</p>
      ) : submissions.length === 0 ? (
        <p>No submissions found.</p>
      ) : (
        <table
          border="1"
          cellPadding="8"
          style={{ width: "100%", borderCollapse: "collapse" }}
        >
          <thead>
            <tr>
              <th>Assignment</th>
              <th>Submitted On</th>
              <th>File</th>
              <th>Grade</th>
            </tr>
          </thead>
          <tbody>
            {submissions.map((sub) => (
              <tr key={sub._id}>
                <td>{sub.assignment.title}</td>
                <td>{new Date(sub.submittedAt).toLocaleDateString()}</td>
                <td>
                  <a
                    href={`http://localhost:5000/${sub.file}`}
                    target="_blank"
                    rel="noreferrer"
                  >
                    Download
                  </a>
                </td>
                <td>{sub.grade != null ? sub.grade : "Not graded yet"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
